// shapes without ever handing a string to a JS evaluator.

function tokenize(src) {
  const tokens = [];
  let i = 0;
  while (i < src.length) {
    const c = src[i];
    if (c === ' ' || c === '\t' || c === '\n' || c === '\r') { i++; continue; }
    if (c === '(' || c === ')') { tokens.push({ type: c }); i++; continue; }
    if (c === '!' && src[i + 1] === '=') {
      const op = src.slice(i, i + 3) === '!==' ? '!==' : '!=';
      tokens.push({ type: 'op', value: op }); i += op.length; continue;
    }
    if (c === '=' && src[i + 1] === '=') {
      const op = src.slice(i, i + 3) === '===' ? '===' : '==';
      tokens.push({ type: 'op', value: op }); i += op.length; continue;
    }
    if (c === '<' || c === '>') {
      const op = src[i + 1] === '=' ? c + '=' : c;
      tokens.push({ type: 'op', value: op }); i += op.length; continue;
    }
    if (c === '&' && src[i + 1] === '&') { tokens.push({ type: 'op', value: '&&' }); i += 2; continue; }
    if (c === '|' && src[i + 1] === '|') { tokens.push({ type: 'op', value: '||' }); i += 2; continue; }
    if (c === '!') { tokens.push({ type: 'op', value: '!' }); i++; continue; }
    if (c === '"' || c === "'") {
      const quote = c; let j = i + 1; let s = '';
      while (j < src.length && src[j] !== quote) {
        if (src[j] === '\\' && j + 1 < src.length) { s += src[j + 1]; j += 2; }
        else { s += src[j]; j++; }
      }
