      let j = i;
      while (j < src.length && /[A-Za-z0-9_.]/.test(src[j])) j++;
      const word = src.slice(i, j);
      if (word === 'true')  tokens.push({ type: 'bool', value: true });
      else if (word === 'false') tokens.push({ type: 'bool', value: false });
      else if (word === 'null')  tokens.push({ type: 'null' });
      else tokens.push({ type: 'ident', value: word });
      i = j; continue;
    }
    throw new Error(`Unexpected character '${c}' at ${i}`);
  }
  return tokens;
}

// Pratt-ish recursive descent. Precedence: || < && < comparison < unary.
function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const eat  = (t, v) => {
    const tk = tokens[pos];
    if (!tk || tk.type !== t || (v !== undefined && tk.value !== v)) {
      throw new Error(`Parse error at token ${pos}`);
    }
    pos++; return tk;
  };

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'op' && peek().value === '||') {
      pos++; const right = parseAnd(); left = { kind: 'or', left, right };
    }
    return left;
  }
  function parseAnd() {
    let left = parseCmp();
    while (peek() && peek().type === 'op' && peek().value === '&&') {
      pos++; const right = parseCmp(); left = { kind: 'and', left, right };
    }
    return left;
  }
  const CMP = new Set(['==', '!=', '===', '!==', '<', '<=', '>', '>=']);
  function parseCmp() {
    let left = parseUnary();
    while (peek() && peek().type === 'op' && CMP.has(peek().value)) {
      const op = peek().value; pos++;
      const right = parseUnary();
      left = { kind: 'cmp', op, left, right };
    }
    return left;
  }
  function parseUnary() {
    if (peek() && peek().type === 'op' && peek().value === '!') {
      pos++; return { kind: 'not', expr: parseUnary() };
    }
    return parsePrimary();
  }
  function parsePrimary() {
    const tk = peek();
    if (!tk) throw new Error('Unexpected end of expression');
    if (tk.type === '(') { pos++; const e = parseOr(); eat(')'); return e; }
    if (tk.type === 'number' || tk.type === 'string' || tk.type === 'bool') {
      pos++; return { kind: 'lit', value: tk.value };
    }
    if (tk.type === 'null') { pos++; return { kind: 'lit', value: null }; }
    if (tk.type === 'ident') {
      pos++;
      const path = tk.value.split('.');
      if (path[0] !== 'ctx') throw new Error(`Identifier must be rooted at 'ctx', got '${path[0]}'`);
      return { kind: 'path', path: path.slice(1) };
    }
    throw new Error(`Unexpected token ${tk.type}`);
  }

  const ast = parseOr();
  if (pos !== tokens.length) throw new Error('Trailing tokens after expression');
  return ast;
}

function evalAst(node, ctx) {
  switch (node.kind) {
    case 'lit': return node.value;
    case 'path': {
      let cur = ctx;
      for (const k of node.path) {
        if (cur == null) return undefined;
        // Only own, non-prototype props — blocks __proto__, constructor, etc.
        if (!Object.prototype.hasOwnProperty.call(cur, k)) return undefined;
        cur = cur[k];
      }
      return cur;
    }
    case 'not': return !evalAst(node.expr, ctx);
    case 'and': return evalAst(node.left, ctx) && evalAst(node.right, ctx);
    case 'or':  return evalAst(node.left, ctx) || evalAst(node.right, ctx);
    case 'cmp': {
      const a = evalAst(node.left, ctx), b = evalAst(node.right, ctx);
      switch (node.op) {
        case '==':  return a == b;   // eslint-disable-line eqeqeq
        case '!=':  return a != b;   // eslint-disable-line eqeqeq
        case '===': return a === b;
        case '!==': return a !== b;
        case '<':   return a <  b;
        case '<=':  return a <= b;
        case '>':   return a >  b;
        case '>=':  return a >= b;
      }
    }
